'use strict';
/* Présentation des résultats serveur uniquement : aucune formule financière navigateur. */
(function(){
 const escape=v=>String(v??'Indisponible').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function table(rows){return '<div class="table-scroll"><table><thead><tr><th>ÉLÉMENT</th><th>RÉSULTAT SERVEUR</th></tr></thead><tbody>'+rows.map(([k,v])=>'<tr><td>'+escape(k)+'</td><td>'+escape(typeof v==='object'&&v!==null?JSON.stringify(v):v)+'</td></tr>').join('')+'</tbody></table></div>'}
 function mount(view){const s=window.CreditServices,d=window.CreditJourney?.getDraft();if(!s?.ready||!s.staff||!d)return;
  const actions=view.querySelector('#server-actions');if(actions){const button=document.createElement('button');button.className='outline';button.id='financial-v2-options';button.textContent='Paramètres de l’analyse approfondie';actions.append(button);button.onclick=()=>{openModal('<h2>Hypothèses et politique explicites</h2><p>La politique doit être installée et approuvée côté serveur pour ce produit et cette institution. Les données complémentaires restent déclarées, sauf rattachement contrôlé. Aucun champ financier absent ne sera inventé.</p><form id="financial-v2-form"><label class="field"><span>Configuration JSON : policy_id, facts, scenarios, reverse_tests, financing_candidates</span><textarea name="options" rows="16" required>'+escape(JSON.stringify(d.financialV2Options||{policy_id:null,facts:{},scenarios:[],reverse_tests:[],financing_candidates:[]},null,2))+'</textarea></label><button class="primary" type="submit">Enregistrer les paramètres</button><p role="status" id="financial-v2-message"></p></form>','MOTEUR FINANCIER V2');document.querySelector('#financial-v2-form').onsubmit=async e=>{e.preventDefault();try{const value=JSON.parse(new FormData(e.target).get('options'));const allowed=['policy_id','facts','scenarios','reverse_tests','financing_candidates'];if(!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).some(k=>!allowed.includes(k)))throw Error('Utilisez uniquement les paramètres indiqués.');d.financialV2Options=value;await s.saveDraft(d);document.querySelector('#modal').close();toast('Paramètres enregistrés. Le serveur les validera à l’analyse.')}catch(err){document.querySelector('#financial-v2-message').textContent=err.message}}};}
  const report=s.publishedReport;if(report?.engine_version!=='financial_analysis_v2'||!['analysis','support'].includes(location.hash.slice(1)))return;const deep=report.deep_analysis,panel=document.createElement('section');panel.className='assumptions-section';panel.id='financial-v2-results';panel.innerHTML='<div><span class="mini-kicker">ANALYSE APPROFONDIE</span><h2>Hypothèses visibles. Résultats traçables.</h2></div>'+[
   ['Historique fourni',Object.entries(deep.history)],['Rapprochement des sources',Object.entries(deep.reconciliation)],
   ['Règles et contraintes produit',[['Règles',report.scoring.rules],['Contraintes',deep.product_constraints]]],
   ['Scénarios et trésorerie',deep.scenarios.map(x=>[x.scenario.name,{statut:x.status,comparaison:x.comparison,informations:x.information_requested,épuisement_réserve:x.reserve_exhaustion_date}])],
   ['Seuils de rupture',deep.reverse_tests.map(x=>[x.parameters.parameter,x])],
   ['Variantes de financement',deep.financing_variants.variants.map(x=>[x.parameters,{statut:x.status,compatible:x.compatible,contraintes:x.constraints,conditions_initiales:x.terms_before,conditions_simulées:x.terms_after,avant:x.before,après:x.after,motif:x.reason,hypothèses:x.assumptions}])]
  ].map(([title,rows])=>'<details><summary>'+escape(title)+' <span>＋</span></summary>'+ (rows.length?table(rows):'<p>Aucun paramètre fourni ; résultat indisponible.</p>')+'</details>').join('')+'<p>Les seuils testés et le montant compatible ne sont ni une probabilité de défaut, ni un conseil de dette maximale, ni un accord de crédit.</p>';view.append(panel);
 }
 window.CreditFinancialV2={mount};
})();
